int delete_tail(List* l) {
    if (!l || !l->tail) return -1;
    Node* p = l->tail;
    p->prev->next = NULL;
    if (p->prev == l->head)
        l->tail = NULL;
    else
        l->tail = p->prev;
    free(p);
    return 0;
}

