    Node* prev = node->prev;
    Node* next = node->next;
    if (prev == l->head) return 0;
    if (next == NULL) {
        prev->next = NULL;
        l->tail = prev;
    } else {
        prev->next = next;
        next->prev = prev;
    }
    node->prev = node->next = NULL;
    link_head(l, node);
    return 0;
}

