    println!("长度: {}", s.len());
}

fn main() {
    let s = String::from("hello");
    print_length(&s);       // 借出去
    println!("{}", s);      // ✓ 还能用，只是借了一下
}
```

### 3.3 可变借用 `&mut T`

```rust
fn append_exclamation(s: &mut String) {
    s.push_str("!");
}

fn main() {
    let mut s = String::from("hello");
    append_exclamation(&mut s);
    println!("{}", s);  // "hello!"
}
